// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/ping", wrapper.Ping)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health/live", wrapper.HealthLive)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health/ready", wrapper.HealthReady)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/accounts/resolve", wrapper.ResolveBillingAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/billing/v1/accounts/{accountScopeKey}/balance", wrapper.ReadBillingBalance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/billing/v1/admin/accounts/{accountScopeKey}/exposure", wrapper.ReadAdminExposure)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/billing/v1/admin/accounts/{accountScopeKey}/ledger", wrapper.ReadAdminLedger)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/microleases/close", wrapper.CloseMicrolease)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/microleases/issue", wrapper.IssueMicrolease)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/microleases/readback", wrapper.ReadMicrolease)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/operations/readback", wrapper.ReadBillingOperation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/billing/v1/reconciliation/cases", wrapper.ListReconciliationCases)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/usage/finalizations", wrapper.FinalizeUsage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/usage/readback", wrapper.ReadUsageOperation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/usage/reservations", wrapper.ReserveUsage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/usage/reversals", wrapper.ReverseUsage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/billing/v1/usage/write-offs", wrapper.WriteOffUsage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/metrics", wrapper.Metrics)
	})

	return r
}

