// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Billing service ping endpoint
	// (GET /api/v1/ping)
	Ping(ctx context.Context, request PingRequestObject) (PingResponseObject, error)
	// Liveness probe
	// (GET /health/live)
	HealthLive(ctx context.Context, request HealthLiveRequestObject) (HealthLiveResponseObject, error)
	// Readiness probe
	// (GET /health/ready)
	HealthReady(ctx context.Context, request HealthReadyRequestObject) (HealthReadyResponseObject, error)
	// Resolve represented caller identity to a billing account
	// (POST /internal/billing/v1/accounts/resolve)
	ResolveBillingAccount(ctx context.Context, request ResolveBillingAccountRequestObject) (ResolveBillingAccountResponseObject, error)
	// Read authoritative billing balance and active exposure
	// (GET /internal/billing/v1/accounts/{accountScopeKey}/balance)
	ReadBillingBalance(ctx context.Context, request ReadBillingBalanceRequestObject) (ReadBillingBalanceResponseObject, error)
	// Read active exposure and worker gate state for an account
	// (GET /internal/billing/v1/admin/accounts/{accountScopeKey}/exposure)
	ReadAdminExposure(ctx context.Context, request ReadAdminExposureRequestObject) (ReadAdminExposureResponseObject, error)
	// Read support-safe ledger history for an account
	// (GET /internal/billing/v1/admin/accounts/{accountScopeKey}/ledger)
	ReadAdminLedger(ctx context.Context, request ReadAdminLedgerRequestObject) (ReadAdminLedgerResponseObject, error)
	// Close or checkpoint a microlease with allocator proof
	// (POST /internal/billing/v1/microleases/close)
	CloseMicrolease(ctx context.Context, request CloseMicroleaseRequestObject) (CloseMicroleaseResponseObject, error)
	// Issue or replenish a billing microlease
	// (POST /internal/billing/v1/microleases/issue)
	IssueMicrolease(ctx context.Context, request IssueMicroleaseRequestObject) (IssueMicroleaseResponseObject, error)
	// Read a microlease or stored operation outcome
	// (POST /internal/billing/v1/microleases/readback)
	ReadMicrolease(ctx context.Context, request ReadMicroleaseRequestObject) (ReadMicroleaseResponseObject, error)
	// Read a stored operation outcome
	// (POST /internal/billing/v1/operations/readback)
	ReadBillingOperation(ctx context.Context, request ReadBillingOperationRequestObject) (ReadBillingOperationResponseObject, error)
	// List support-safe reconciliation cases
	// (GET /internal/billing/v1/reconciliation/cases)
	ListReconciliationCases(ctx context.Context, request ListReconciliationCasesRequestObject) (ListReconciliationCasesResponseObject, error)
	// Finalize a usage operation within microlease authority
	// (POST /internal/billing/v1/usage/finalizations)
	FinalizeUsage(ctx context.Context, request FinalizeUsageRequestObject) (FinalizeUsageResponseObject, error)
	// Read usage operation state by durable usage identity
	// (POST /internal/billing/v1/usage/readback)
	ReadUsageOperation(ctx context.Context, request ReadUsageOperationRequestObject) (ReadUsageOperationResponseObject, error)
	// Create or read back migrated usage reserve lineage
	// (POST /internal/billing/v1/usage/reservations)
	ReserveUsage(ctx context.Context, request ReserveUsageRequestObject) (ReserveUsageResponseObject, error)
	// Reverse a previously committed usage effect
	// (POST /internal/billing/v1/usage/reversals)
	ReverseUsage(ctx context.Context, request ReverseUsageRequestObject) (ReverseUsageResponseObject, error)
	// Write off or release a usage operation explicitly
	// (POST /internal/billing/v1/usage/write-offs)
	WriteOffUsage(ctx context.Context, request WriteOffUsageRequestObject) (WriteOffUsageResponseObject, error)
	// Prometheus metrics
	// (GET /metrics)
	Metrics(ctx context.Context, request MetricsRequestObject) (MetricsResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

